-- じっくりコース（basic）の学習カード: 基礎をていねいに4枚
INSERT OR REPLACE INTO learning_cards (card_id, subject, grade_level, unit_name, card_title, card_type, difficulty_level, learning_track, problem_text, problem_description, correct_answer, explanation, hint_text, card_order, estimated_time_minutes, is_active, course_id) VALUES
(99011, '算数', '小学5年', '小数のかけ算', '小数ってなんだろう？', 'standard', 'easy', 'jikkuri', '0.3×4の計算をしましょう。0.3は0.1がいくつ分ですか？', '小数の意味を確認しながら、小数×整数の基本を学びます', '0.3は0.1が3つ分。0.3×4=1.2', '0.1をもとにして考えると、0.1が3つ分で0.3、それが4つで0.1が12こ分＝1.2', '0.1がいくつあるか数えてみよう', 1, 15, 1, 99001),
(99012, '算数', '小学5年', '小数のかけ算', '小数×整数をマスター', 'standard', 'easy', 'jikkuri', '2.3×3を筆算で計算しましょう', '小数×整数の筆算のやり方をていねいに練習します', '2.3×3=6.9', '整数のかけ算と同じように計算して、最後に小数点をつけます。23×3=69なので、小数点を1つもどして6.9', 'まず整数のかけ算として計算してみよう', 2, 15, 1, 99001),
(99013, '算数', '小学5年', '小数のかけ算', '小数×小数のしくみ', 'standard', 'standard', 'jikkuri', '1.2×0.3を計算しましょう。面積図を使って考えてみよう', '小数×小数の意味を面積図で理解します', '1.2×0.3=0.36', '面積図で考えると、たて1.2、よこ0.3の長方形の面積。12×3=36なので、小数点を2つもどして0.36', '面積図をかいて、たてとよこの長さを確認しよう', 3, 20, 1, 99001),
(99014, '算数', '小学5年', '小数のかけ算', '小数のかけ算まとめ', 'standard', 'standard', 'jikkuri', '次の計算をしましょう。①0.7×6 ②3.4×2.5 ③0.08×0.5', 'これまでの学習のまとめ問題です', '①4.2 ②8.5 ③0.04', '①7×6=42→4.2 ②34×25=850→8.50=8.5 ③8×5=40→0.040=0.04', '整数として計算してから、小数点の位置を決めよう', 4, 20, 1, 99001);

-- ぐんぐんコース（advanced）の学習カード: 発展問題含む6枚
INSERT OR REPLACE INTO learning_cards (card_id, subject, grade_level, unit_name, card_title, card_type, difficulty_level, learning_track, problem_text, problem_description, correct_answer, explanation, hint_text, card_order, estimated_time_minutes, is_active, course_id) VALUES
(99021, '算数', '小学5年', '小数のかけ算', '小数×整数をサクッと', 'standard', 'easy', 'gungun', '次の計算を暗算でしましょう。①0.5×8 ②1.4×3 ③0.25×4', '小数×整数の計算を素早くできるようにします', '①4 ②4.2 ③1', '暗算のコツ：0.5×8は半分の4、0.25×4は1/4が4つで1', '0.5は1/2、0.25は1/4と考えると暗算しやすいよ', 1, 10, 1, 99003),
(99022, '算数', '小学5年', '小数のかけ算', '小数×小数の筆算マスター', 'standard', 'standard', 'gungun', '3.14×2.5を筆算で計算しましょう', '小数×小数の筆算を正確に速くできるようにします', '3.14×2.5=7.85', '314×25=7850。小数点は合計3つ分（2+1）もどして7.850=7.85', '小数点の位置は、かける数とかけられる数の小数点以下のケタ数を足した分だけもどす', 2, 10, 1, 99003),
(99023, '算数', '小学5年', '小数のかけ算', '面積と小数のかけ算', 'standard', 'standard', 'gungun', 'たて2.4m、よこ3.5mの長方形の花だんの面積は何㎡？', '小数のかけ算を面積の問題に活用します', '2.4×3.5=8.4㎡', '面積＝たて×よこ。24×35=840。小数点を2つもどして8.40＝8.4', '面積の公式：たて×よこ', 3, 15, 1, 99003),
(99024, '算数', '小学5年', '小数のかけ算', '計算のきまりを発見', 'standard', 'hard', 'gungun', '0.1×0.1はいくつ？0.01×0.1は？ 小数をかけると答えはどうなる？きまりを見つけよう', '小数をかけると数が小さくなるきまりを発見します', '0.1×0.1=0.01、0.01×0.1=0.001。1より小さい数をかけると答えは元の数より小さくなる', 'かけ算は「いつも数が大きくなる」わけではない！1より小さい数をかけると小さくなります', '1×0.1、2×0.1を計算して、答えが元の数より大きいか小さいか調べよう', 4, 15, 1, 99003),
(99025, '算数', '小学5年', '小数のかけ算', '工夫して計算しよう', 'challenge', 'hard', 'gungun', '2.5×3.7×4を工夫して計算しましょう。（ヒント：計算の順番を変えてよい）', '計算のきまりを使って工夫する力をつけます', '2.5×4=10、10×3.7=37。答えは37', 'かけ算の交換法則・結合法則を使って、まず2.5×4=10を作ると計算が楽になる', 'かけ算は順番を変えても答えは同じ。きりのいい数を先に計算しよう', 5, 15, 1, 99003),
(99026, '算数', '小学5年', '小数のかけ算', '発展：小数のかけ算の文章題', 'challenge', 'hard', 'gungun', '1mが0.8kgのパイプがあります。このパイプ2.5m分の重さは何kgですか？また、0.6m分では？', '小数のかけ算を使った実生活の問題に挑戦します', '2.5m→0.8×2.5=2kg、0.6m→0.8×0.6=0.48kg', '1mあたりの重さ×長さ＝全体の重さ。0.8×2.5=2.0、0.8×0.6=0.48', '「1mあたり」の重さがわかっているので、ほしい長さをかければOK', 6, 20, 1, 99003);

